}

.pricing-card-features li svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--green);
}

.pricing-card .btn {
  margin-top: 8px;
}

.pricing-card-divider {
  height: 1px;
  background: var(--border);
  margin: 24px 0;
}

.pricing-see-all {
  text-align: center;
  margin-top: 32px;
  font-size: 14px;
  color: var(--primary);
  font-weight: 600;
  cursor: pointer;
  display: none;
}

.pricing-see-all.visible {
  display: block;
}

/* Comparison table */
.comparison-section {
  padding: 80px 0;
  background: var(--bg);
}

.comparison-table-wrap {
  overflow-x: auto;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--white);
  margin-top: 48px;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 800px;
}

.comparison-table th {
  padding: 16px 20px;
  text-align: center;
  font-size: 15px;
  font-weight: 700;
  border-bottom: 2px solid var(--border);
  background: var(--white);
}

.comparison-table th:first-child {
  text-align: left;
  width: 280px;
}

.comparison-table td {
  padding: 14px 20px;
  font-size: 14px;
  border-bottom: 1px solid var(--border);
  text-align: center;
}

.comparison-table td:first-child {
  text-align: left;
  font-weight: 500;
  color: var(--text);
}

.comparison-table tr:last-child td {
  border-bottom: none;
}

.comparison-table tr:hover td {
  background: var(--bg);
}

.check-ico { color: var(--green); }
.dash-ico { color: var(--text-muted); }

/* FAQ */
.faq-section {
  padding: 80px 0;
}

.faq-list {
  max-width: 800px;
  margin: 48px auto 0;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 16px;
  font-weight: 600;
  font-family: var(--font);
  color: var(--text);
  text-align: left;
  gap: 16px;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-question svg {
  flex-shrink: 0;
  transition: transform 0.3s;
  color: var(--text-muted);
}

.faq-item.open .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding-bottom: 20px;
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* AI Features */
.ai-features {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--indigo) 0%, var(--indigo-dark) 100%);
  color: var(--white);
  text-align: center;
}

.ai-features h2 {
  font-size: 36px;
  font-weight: 800;
  margin-bottom: 12px;
}

.ai-features p {
  font-size: 18px;
  opacity: 0.9;
  margin-bottom: 40px;
}

.ai-features-list {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  max-width: 700px;
  margin: 0 auto 40px;
}

.ai-feature-tag {
  background: rgba(255,255,255,0.15);
  border: 1px solid rgba(255,255,255,0.25);
  padding: 10px 20px;
  border-radius: 30px;
  font-size: 15px;
  font-weight: 500;
}

.ai-features .btn {
  background: var(--white);
  color: var(--indigo);
  font-weight: 700;
}

.ai-features .btn:hover {
  background: var(--indigo-light);
  transform: translateY(-1px);
}

/* ===== LOGIN / SIGNUP ===== */
.auth-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.auth-main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  background: var(--bg);
}

.auth-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  width: 100%;
  max-width: 440px;
  padding: 40px;
}

.auth-header {
  text-align: center;
  margin-bottom: 32px;
}

.auth-logo {
  font-weight: 800;
  font-size: 22px;
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 24px;
}

.auth-title {
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 8px;
}

.auth-subtitle {
  font-size: 15px;
  color: var(--text-secondary);
}

.auth-socials {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 24px;
}

.btn-social {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 20px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  border: 1.5px solid var(--border);
  background: var(--white);
  color: var(--text);
  font-family: var(--font);
  width: 100%;
}

.btn-social:hover {
  background: var(--bg);
  border-color: var(--text-muted);
}

.auth-divider {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
  font-size: 13px;
  color: var(--text-muted);
}

.auth-divider::before,
.auth-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

.auth-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-group label {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.form-group input {
  padding: 12px 16px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 15px;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s;
}

.form-group input:focus {
  border-color: var(--primary);
}

.auth-footer {
  text-align: center;
  margin-top: 24px;
  font-size: 14px;
  color: var(--text-secondary);
}

.auth-footer a {
  color: var(--primary);
  font-weight: 600;
}

/* Signup testimonial sidebar */
.signup-layout {
  max-width: 960px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 48px;
  align-items: center;
}

.signup-sidebar {
  background: var(--indigo);
  border-radius: var(--radius-xl);
  padding: 40px;
  color: var(--white);
}

.signup-sidebar blockquote {
  font-size: 16px;
  line-height: 1.7;
  margin-bottom: 24px;
  font-style: italic;
}

.signup-sidebar cite {
  display: flex;
  align-items: center;
  gap: 12px;
  font-style: normal;
}

.signup-sidebar cite strong {
  display: block;
  font-weight: 700;
}

.signup-sidebar cite span {
  font-size: 13px;
  opacity: 0.8;
}

/* ===== ENTERPRISE PAGE ===== */
.enterprise-hero {
  padding: 80px 0 60px;
  background: linear-gradient(180deg, var(--white) 0%, var(--bg) 100%);
  text-align: center;
}

.enterprise-hero-title {
  font-size: 48px;
  font-weight: 900;
  margin-bottom: 16px;
  line-height: 1.1;
}

.enterprise-hero-subtitle {
  font-size: 20px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

/* Enterprise benefits */
.async-benefits {
  padding: 80px 0;
}

.async-benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.async-benefit {
  text-align: center;
}

.async-benefit-icon {
  width: 56px;
  height: 56px;
  background: var(--indigo-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  color: var(--indigo);
}

.async-benefit h3 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 10px;
}

.async-benefit p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* Community visibility */
.community-visibility {
  padding: 80px 0;
  background: var(--bg);
}

.community-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.community-item h3 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.community-item p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 24px;
}

/* Enterprise stats */
.enterprise-stats {
  padding: 64px 0;
  background: var(--white);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.enterprise-stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.enterprise-stat-number {
  font-size: 44px;
  font-weight: 900;
  color: var(--primary);
  margin-bottom: 8px;
}

.enterprise-stat-label {
  font-size: 16px;
  color: var(--text-secondary);
}

/* Enterprise integrations */
.enterprise-integrations {
  padding: 80px 0;
}

/* Enterprise pricing */
.enterprise-pricing {
  padding: 80px 0;
  background: var(--bg);
}

/* Testimonials carousel */
.enterprise-testimonials {
  padding: 80px 0;
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  max-width: 420px;
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  padding: 24px;
  z-index: 1000;
  display: none;
  border: 1px solid var(--border);
}

.cookie-banner.show {
  display: block;
  animation: slideUp 0.3s ease;
}

@keyframes slideUp {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.cookie-banner h3 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
}

.cookie-banner p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
  margin-bottom: 16px;
}

.cookie-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

/* Cookie modal */
.cookie-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1001;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.cookie-modal-overlay.show {
  display: flex;
}

.cookie-modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  max-width: 480px;
  width: 100%;
  padding: 32px;
  max-height: 80vh;
  overflow-y: auto;
}

.cookie-modal h2 {
  font-size: 22px;
  font-weight: 800;
  margin-bottom: 8px;
}

.cookie-modal > p {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

.cookie-category {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px;
  margin-bottom: 12px;
}

.cookie-category h4 {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 4px;
}

.cookie-category p {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 12px;
}

.toggle-switch {
  position: relative;
  width: 44px;
  height: 24px;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-slider {
  position: absolute;
  inset: 0;
  background: var(--border);
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s;
}

.toggle-slider::before {
  content: '';
  position: absolute;
  width: 18px;
  height: 18px;
  background: var(--white);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: transform 0.2s;
  box-shadow: var(--shadow-sm);
}

.toggle-switch input:checked + .toggle-slider {
  background: var(--indigo);
}

.toggle-switch input:checked + .toggle-slider::before {
  transform: translateX(20px);
}

.cookie-modal-actions {
  display: flex;
  gap: 8px;
  margin-top: 24px;
}

/* Responsive */
@media (max-width: 1024px) {
  .pricing-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .signup-layout {
    grid-template-columns: 1fr;
  }

  .signup-sidebar {
    display: none;
  }
}

@media (max-width: 768px) {
  .hero-title {
    font-size: 36px;
  }

  .section-title {
    font-size: 28px;
  }

  .nav-links {
    display: none;
  }

  .grid-2, .grid-3, .grid-4 {
    grid-template-columns: 1fr;
  }

  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .use-cases-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid-outer {
    grid-template-columns: repeat(2, 1fr);
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }

  .enterprise-hero-title {
    font-size: 32px;
  }

  .async-benefits-grid,
  .enterprise-stats-grid {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .community-grid,
  .feature-highlight-grid,
  .feature-block-grid {
    grid-template-columns: 1fr;
  }

  .feature-block-grid.reverse {
    direction: ltr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .hero {
    padding: 48px 0 40px;
  }

  .hero-title {
    font-size: 28px;
  }

  .use-cases-grid,
  .features-grid-outer {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .blog-grid {
    grid-template-columns: 1fr;
  }

  .auth-card {
    padding: 28px 20px;
  }
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in-up {
  animation: fadeInUp 0.5s ease forwards;
}

/* Scroll animations */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

